package com.citacloud.app.repositories; import com.citacloud.app.models.ExistenciaInventario; import org.springframework.data.jpa.repository.*; import jakarta.persistence.LockModeType; import java.util.*; public interface ExistenciaInventarioRepository extends JpaRepository<ExistenciaInventario,UUID>{@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select e from ExistenciaInventario e where e.empresaId=:empresa and e.sucursal.id=:sucursal and e.producto.id=:producto") Optional<ExistenciaInventario> bloquear(UUID empresa,UUID sucursal,UUID producto); List<ExistenciaInventario> findByEmpresaIdAndProductoId(UUID empresa,UUID producto);}
